export function createOptimisticStore(initialState) {
  let base = initialState;
  let visible = initialState;
  let pending = new Map();
  const subscriptions = new Set();

  function notify() {
    // Subscription changes cannot disturb this notification's ordering.
    const snapshot = Array.from(subscriptions);
    for (const { listener } of snapshot) {
      try {
        listener();
      } catch {
        // One listener's failure must not prevent the others from running.
      }
    }
  }

  function settle(id, shouldConfirm) {
    if (!pending.has(id)) {
      return false;
    }

    const update = pending.get(id);
    const nextPending = new Map(pending);
    nextPending.delete(id);

    const nextBase = shouldConfirm ? update(base) : base;
    let nextVisible = nextBase;

    for (const pendingUpdate of nextPending.values()) {
      nextVisible = pendingUpdate(nextVisible);
    }

    // Commit only after every required update has completed successfully.
    base = nextBase;
    pending = nextPending;
    visible = nextVisible;

    notify();
    return true;
  }

  return {
    getState() {
      return visible;
    },

    apply(id, update) {
      if (pending.has(id)) {
        throw new Error("A change with this id is already pending.");
      }

      const nextVisible = update(visible);
      pending.set(id, update);
      visible = nextVisible;
      notify();
    },

    confirm(id) {
      return settle(id, true);
    },

    rollback(id) {
      return settle(id, false);
    },

    subscribe(listener) {
      // Separate records make each subscription independently removable.
      const subscription = { listener };
      subscriptions.add(subscription);

      return () => {
        subscriptions.delete(subscription);
      };
    },
  };
}
